      Container(padding:const EdgeInsets.all(12), color:const Color(0xFF1A2332), child:Row(mainAxisAlignment:MainAxisAlignment.spaceBetween, children:[Row(children:[const CircleAvatar(radius:16, backgroundImage:NetworkImage('https://i.pravatar.cc/100?img=12')), const SizedBox(width:6), Container(padding:const EdgeInsets.symmetric(horizontal:10,vertical:5), decoration:BoxDecoration(color:Colors.black45, borderRadius:BorderRadius.circular(20)), child:const Text("🪙 1500 +", style:TextStyle(color:Colors.white, fontSize:11))), const SizedBox(width:6), GestureDetector(onTap:showReq, child:Container(padding:const EdgeInsets.all(6), decoration:BoxDecoration(color:Colors.black26, borderRadius:BorderRadius.circular(20)), child:const Text("👥 2", style:TextStyle(color:Colors.white, fontSize:11))))]), const Text("🔍 👑 TOP", style:TextStyle(color:Colors.white, fontSize:11)) ])),
      Expanded(child:SingleChildScrollView(child:Column(children:[
        Padding(padding:const EdgeInsets.all(14), child:GridView.count(shrinkWrap:true, physics:const NeverScrollableScrollPhysics(), crossAxisCount:2, childAspectRatio:0.85, mainAxisSpacing:14, crossAxisSpacing:12, children:[
          _prettyCard(context,"بلياردو",[const Color(0xFFFF9800), const Color(0xFF5D4037)],"🎯", BilliardScreen(chat:globalChat)),
          _prettyCard(context,"دومينو 50",[const Color(0xFF66BB6A), const Color(0xFF1B5E20)],"🀄", DominoScreen(chat:globalChat)),
